// Individually authored wording. Option IDs/keys and legal hypotheses stay fixed.
module.exports={
'CC-010':{
 reason:'Giới thiệu Lan nhất quán; bỏ lời dẫn về danh sách thân thích; nhiễu dựa vào hiểu sai phạm vi xung đột lợi ích.',
 variants:[
  'Tháng 10/2026, công chứng viên Lan nhận hồ sơ bán tài sản riêng của mẹ nuôi chồng mình. Lan không có quyền lợi trong tài sản đó. Lan nên xử lý hồ sơ thế nào?',
  'Tháng 10/2026, mẹ nuôi của chồng Lan nhờ Lan công chứng hợp đồng bán tài sản riêng. Hai người không sống cùng nhà và các bên đều đồng ý bằng văn bản để Lan thực hiện. Lan có thể nhận công chứng không?'
 ],
 options:{B:['Lan có thể thực hiện vì giao dịch không làm phát sinh quyền, nghĩa vụ tài sản cho Lan.','Lệnh cấm còn bao gồm giao dịch liên quan tài sản, lợi ích của người thân thích được liệt kê.'],C:['Lan có thể thực hiện sau khi công khai quan hệ và được các bên chấp thuận bằng văn bản.','Sự chấp thuận của các bên không tạo ngoại lệ cho quan hệ thân thích này.'],D:['Lan có thể thực hiện nếu xác minh người bán không cùng hộ gia đình với mình.','Việc sống khác hộ không loại mẹ nuôi của chồng khỏi phạm vi luật định.']}
},
'CC-046':{
 reason:'Giữ rõ mốc 2027; chuyển câu hỏi về hồ sơ thực tế, bỏ cách gọi sẵn ngoại lệ.',
 variants:[
  'Từ 01/01/2027, bà H yêu cầu công chứng văn bản từ chối nhận di sản là quyền sử dụng đất. Bà đã cung cấp đủ giấy tờ chứng minh tư cách thừa kế và việc người để lại di sản đã chết, nhưng không có bản chính giấy tờ đất để đối chiếu. Yêu cầu xuất trình giấy tờ đất được xử lý thế nào?',
  'Từ 01/01/2027, một hồ sơ từ chối nhận di sản đất đã có đủ giấy tờ về người để lại di sản và tư cách người từ chối. Bộ phận tiếp nhận yêu cầu bổ sung bản chính giấy tờ tài sản trước khi công chứng. Yêu cầu bổ sung này có phù hợp không?'
 ],
 options:{A:['Chỉ không yêu cầu bản chính khi người từ chối chưa từng quản lý hoặc sử dụng thửa đất.','Ngoại lệ không đặt thêm điều kiện người từ chối chưa quản lý hay sử dụng tài sản.'],B:['Có thể dùng giấy tờ chứng minh tư cách thừa kế thay cả giấy tờ chứng minh người để lại di sản đã chết.','Ngoại lệ đối chiếu giấy tờ tài sản không thay các thành phần chứng minh khác.'],C:['Áp dụng cùng cách xử lý bản chính giấy tờ tài sản cho hồ sơ phân chia di sản đã đủ người thừa kế.','Không mở rộng ngoại lệ của văn bản từ chối sang văn bản phân chia di sản.']}
},
'IMP-SEP24-031':{
 reason:'Bỏ lời nhắc so sánh đất giao với đất thuê; nhiễu cùng xoay quanh thủ tục và thời hạn thuê tiếp.',
 variants:[
  'Tháng 10/2026, bà H hết hạn thuê đất nông nghiệp của Nhà nước theo điểm b khoản 1 Điều 172 Luật Đất đai. Bà vẫn trực tiếp sản xuất và đã nộp đề nghị thuê tiếp. Đề nghị này được giải quyết theo cách nào?',
  'Tháng 10/2026, hồ sơ của bà H đề nghị tiếp tục thuê đất nông nghiệp khi thời hạn thuê theo điểm b khoản 1 Điều 172 đã hết. Bà còn nhu cầu sử dụng nhưng chưa có quyết định giải quyết. Phương án nào đúng về việc thuê tiếp?',
  'Tháng 10/2026, bà H muốn tiếp tục sử dụng diện tích đất nông nghiệp đang thuê của Nhà nước sau khi hợp đồng hết hạn. Việc thuê thuộc điểm b khoản 1 Điều 172 và bà đã gửi đơn đề nghị. Cơ quan có thẩm quyền cần xử lý thế nào?'
 ],
 options:{A:['Tiếp tục sử dụng thêm 50 năm theo kỳ thuê cũ, chỉ cần cập nhật thời hạn trên hồ sơ địa chính.','Thuê tiếp phải được xem xét, không tự nối thêm một kỳ chỉ bằng cập nhật hồ sơ.'],B:['Được xem xét thuê tiếp tối đa 99 năm nếu vẫn trực tiếp sản xuất nông nghiệp.','Nhánh thuê đất trong đề có giới hạn 50 năm, không phải 99 năm.'],C:['Phải làm thủ tục chuyển sang giao đất không thu tiền rồi mới được tiếp tục sử dụng.','Nhu cầu thuê tiếp không làm phát sinh yêu cầu chuyển sang hình thức giao đất.']}
},
'FAM26-002':{
 reason:'Bỏ câu hỏi gợi sẵn sự khác nhau giữa hai nhóm giấy; giữ giả thiết điểm d và chưa khai thác dữ liệu.',
 variants:[
  'Tháng 10/2026, vợ chồng H mang bản sao chứng thực căn cước và giấy đăng ký kết hôn để công chứng thỏa thuận tài sản; cả hai bản chính đều không có. Văn phòng chưa khai thác được dữ liệu tương ứng. Giấy kết hôn trong hồ sơ thuộc điểm d khoản 1 Điều 42. Trước khi ký lời chứng, công chứng viên xử lý các giấy tờ này thế nào?',
  'Tháng 10/2026, một hồ sơ thỏa thuận tài sản vợ chồng chỉ có bản sao chứng thực giấy tờ tùy thân và giấy kết hôn, không có bản chính. Văn phòng chưa khai thác được thông tin từ cơ sở dữ liệu; giấy kết hôn là giấy tờ liên quan thuộc điểm d khoản 1 Điều 42. Hồ sơ có cần bổ sung gì trước khi công chứng viên ký lời chứng?',
  'Tháng 10/2026, người yêu cầu công chứng thỏa thuận tài sản cho rằng hai bản sao chứng thực căn cước và giấy kết hôn đã đủ để đối chiếu. Họ không mang bản chính; dữ liệu chưa được khai thác và giấy kết hôn thuộc điểm d khoản 1 Điều 42. Công chứng viên nên trả lời thế nào?'
 ],
 options:{A:['Có thể dùng bản sao chứng thực căn cước; giấy kết hôn phải bổ sung bản chính vì quyết định tư cách vợ chồng.','Phương án đảo ngược phạm vi ngoại lệ ở điểm d và yêu cầu đối chiếu giấy tờ tùy thân.'],B:['Có thể dùng cả hai bản sao chứng thực nếu dấu chứng thực và thông tin nhân thân đều còn rõ.','Tình trạng bản sao không làm ngoại lệ ở điểm d áp dụng sang giấy tờ tùy thân tại điểm b.'],D:['Cần bổ sung bản chính của cả hai giấy tờ vì văn phòng chưa khai thác được dữ liệu.','Chưa khai thác dữ liệu không loại ngoại lệ riêng cho giấy tờ thuộc điểm d.']}
},
'CAL26-015':{
 reason:'Bỏ hướng dẫn tách tài sản và nhận diện người thừa kế bắt buộc khỏi câu dẫn; sửa nhiễu thành phép tính sai hợp lý.',
 variants:['Tài sản chung của vợ chồng M, N trị giá 6 tỷ đồng; không có tài sản riêng, nghĩa vụ phải trừ hoặc thỏa thuận chia khác. M chết, cha mẹ đều đã chết. Ba người con là P 17 tuổi, Q thành niên có khả năng lao động và R thành niên không có khả năng lao động. Di chúc để toàn bộ phần tài sản của M cho bạn H; N và các con không từ chối, không mất quyền hưởng. Những kết luận nào đúng về phần mỗi người được nhận?'],
 options:{B:['N, P và R mỗi người nhận 666⅔ triệu đồng từ di sản vì suất theo pháp luật được tính cho ba người này.','Suất giả định theo pháp luật còn tính cả Q; Q không có phần bắt buộc không có nghĩa bị loại khỏi mẫu số.']}
},
'CAL26-021':{
 reason:'Giữ tình huống có hai việc cần xử lý, dùng câu hỏi mở về thủ tục thay cho chỉ dẫn phân loại.',
 variants:['Hợp đồng bán nhà ghi giá 2 tỷ đồng, đúng ý chí các bên khi ký. Nay hai bên thống nhất giảm giá còn 1,8 tỷ đồng và đề nghị sửa luôn một lỗi đánh máy tên đường. Đối chiếu hồ sơ cho thấy sửa tên đường không ảnh hưởng quyền, nghĩa vụ. Hai bên muốn ghi cả hai thay đổi ở lề rồi gửi thông báo. Công chứng viên nên xử lý thế nào?'],
 options:{A:['Sửa cả giá và tên đường theo thủ tục sửa lỗi kỹ thuật vì các bên cùng xác nhận và hồ sơ gốc đầy đủ.','Đồng thuận mới về giá không phải lỗi ghi chép so với ý chí lúc ký.'],B:['Công chứng sửa đổi cả hai nội dung vì lỗi tên đường nằm trong hợp đồng về bất động sản.','Loại tài sản không làm mất cơ chế sửa lỗi kỹ thuật khi đủ điều kiện.'],C:['Sửa giá theo thủ tục kỹ thuật nếu chưa thanh toán; riêng tên đường phải công chứng sửa đổi hợp đồng.','Tình trạng thanh toán không biến thay đổi giá thành lỗi kỹ thuật; hai cách xử lý bị đảo ngược.']}
},
'CAL26-027':{
 reason:'Viết liền mạch hai tình huống ký; giảm nhiễu gồm hai mệnh đề vô lý cùng lúc.',
 variants:['A có thể ký nhưng đề nghị ký kèm điểm chỉ trên văn bản giấy. B không ký được; cả hai ngón trỏ không sử dụng được, còn ngón giữa phải vẫn dùng được. Không trường hợp nào được ký trước theo chữ ký mẫu. Những nhận định nào đúng về việc ký, điểm chỉ của A và B?'],
 options:{A:['A chỉ được ký kèm điểm chỉ khi công chứng viên yêu cầu; đề nghị riêng của A chưa đủ để thực hiện.','Khoản 4 Điều 50 còn cho phép ký kèm điểm chỉ theo đề nghị của người yêu cầu công chứng.']}
},
'CAL26-047':{
 reason:'Bỏ gợi ý trần trách nhiệm; để người làm tự xác định cách xử lý khoản nợ sau chia.',
 variants:['Di sản 600 triệu đồng đã được chia cho A 400 triệu và B 200 triệu. Sau đó phát hiện khoản nợ 900 triệu của người chết. Không ai thỏa thuận trả vượt phần di sản đã nhận. Chủ nợ yêu cầu A trả 600 triệu, B trả 300 triệu, tương ứng tỷ lệ 2:1 khi chia di sản. Yêu cầu này được giải quyết thế nào?'],
 options:{B:['A và B mỗi người chịu tối đa 300 triệu đồng vì phải chia đều nghĩa vụ trong phạm vi tổng di sản.','Phân bổ đều không phản ánh phần di sản A và B đã nhận; trần của B không thể vượt 200 triệu.'],D:['A chịu tối đa 400 triệu đồng; B chỉ trả nợ nếu sau đó có thỏa thuận nhận thêm nghĩa vụ.','B cũng phải thực hiện nghĩa vụ trong phạm vi 200 triệu đã nhận, không cần nhận thêm nghĩa vụ.']}
},
'HARD26-041':{
 reason:'Giữ câu hỏi về thế chấp tiếp; thay nhiễu cấm tuyệt đối và ký thiếu vợ bằng nhầm lẫn thủ tục có thể xảy ra.',
 variants:['Tháng 10/2026, nhà chung của A và W đã được thế chấp cho ngân hàng M, hợp đồng do tổ chức X công chứng. Giá trị nhà đủ bảo đảm các nghĩa vụ theo luật; A, W cùng đồng ý bằng văn bản thế chấp tiếp cho N, M đã được thông báo và hợp đồng không cấm. X vẫn hoạt động. N đề nghị công chứng hợp đồng tiếp tại Y, cũng nằm trong tỉnh có nhà. Đề nghị này được xử lý thế nào?'],
 options:{A:['Có thể chọn Y vì nhà cùng tỉnh; X chỉ cần cung cấp thông tin về hợp đồng thế chấp trước.','Trao đổi thông tin không thay quy tắc về nơi công chứng thế chấp tiếp khi X vẫn hoạt động.'],B:['Phải giải chấp hợp đồng với M trước, sau đó mới xem xét công chứng hợp đồng với N tại Y.','Một tài sản có thể bảo đảm nhiều nghĩa vụ khi đủ điều kiện; không bắt buộc giải chấp trước theo dữ kiện.'],C:['Có thể chọn Y nếu M chấp thuận bằng văn bản việc đổi tổ chức công chứng.','Sự chấp thuận của chủ nợ không thay quy tắc chọn tổ chức đã công chứng lần đầu.']}
},
'HARD26-013':{
 reason:'Cân đối cách trình bày bốn con số để người làm phải tính, không nhận ra đáp án từ kiểu diễn đạt.',
 variants:['Tháng 10/2026, A chết, để lại tài sản riêng 1,5 tỷ đồng và khoản nợ, chi phí hợp lệ tổng cộng 300 triệu đồng. A còn vợ W, con B 16 tuổi và con C 28 tuổi có khả năng lao động; cha mẹ đã chết. Di chúc cho W 100 triệu đồng, phần còn lại cho X. Không ai từ chối hoặc mất quyền hưởng di sản. W cần được bổ sung bao nhiêu để đủ phần thừa kế bắt buộc?'],
 options:{A:['233⅓ triệu đồng.','Tính phần bắt buộc trên 1,5 tỷ sẽ bỏ qua 300 triệu nợ và chi phí phải trừ.'],B:['300 triệu đồng.','Đây là phần thiếu so với một suất pháp luật, chưa áp dụng tỷ lệ hai phần ba.'],C:['266⅔ triệu đồng.','Đây là toàn bộ mức bắt buộc, chưa trừ 100 triệu W đã được hưởng theo di chúc.']}
},
'COMP26-CT-013':{
 reason:'Tách câu dài; giữ ngoại lệ đã loại trừ trong đề nhưng bỏ yêu cầu tự phân tích theo các bước gợi trước.',
 variants:['Tháng 10/2026, D tự dịch giấy tờ dùng cho việc cá nhân và đề nghị công chứng viên K chứng thực chữ ký người dịch. D đủ điều kiện về giấy tờ, năng lực, ngôn ngữ; không phải cộng tác viên dịch thuật và chưa đăng ký chữ ký mẫu. D đã ký ở nhà, chỉ gửi ảnh chữ ký để đối chiếu. Hồ sơ không thuộc ngoại lệ tại khoản 3 Điều 24. K nên giải quyết thế nào?'],
 options:{B:['K phải hướng dẫn D đến Phòng Tư pháp vì người dịch không đăng ký làm cộng tác viên tại văn phòng.','Không phải cộng tác viên không tự loại thẩm quyền của công chứng viên trong trường hợp luật cho phép.'],C:['K có thể đối chiếu chữ ký đã ký với căn cước và ảnh do D cung cấp để hoàn tất chứng thực.','Cách đối chiếu này không thay thủ tục ký khi chưa có mẫu và không thuộc ngoại lệ.'],D:['K cần công chứng bản dịch trước, sau đó mới chứng thực chữ ký D trên bản dịch đã công chứng.','Công chứng nội dung bản dịch không phải bước thay thế cho thủ tục chứng thực chữ ký người dịch.']}
},
'INH26-015':{
 reason:'Bỏ câu dẫn chỉ cách phân biệt; giữ rõ người nhận, thời điểm và ý chí tặng để tránh khái quát tiền phúng viếng.',
 variants:[
  'Tháng 10/2026, sau khi ông Lân chết, một người bạn tặng riêng vợ ông 20 triệu đồng và đã giao tiền. Hai bên xác định khoản tặng chỉ dành cho bà, không dành cho ông Lân hoặc nhóm người thừa kế. Khi lập danh sách di sản, con ông đề nghị đưa cả khoản tiền này vào vì được trao tại tang lễ. Đề nghị đó có phù hợp không?',
  'Tháng 10/2026, bà H nhận 20 triệu đồng từ bạn của chồng sau khi chồng là ông Lân qua đời. Thỏa thuận tặng cho và việc giao tiền đều xác định bà là người được tặng riêng. Các con muốn chia khoản tiền cùng di sản của ông vì tiền được giao trong đám tang. Khoản này được xác định thế nào?',
  'Tháng 10/2026, người quản lý di sản đưa 20 triệu đồng trao tại tang lễ vào danh sách tài sản của ông Lân. Chứng từ cho thấy bạn ông đã tặng riêng khoản tiền cho vợ ông sau khi ông chết, không tặng cho ông hoặc cả gia đình. Danh sách cần được xử lý thế nào?'
 ],
 options:{A:['Ghi vào di sản trước, rồi hoàn lại cho người vợ nếu những người thừa kế cùng chấp thuận.','Tài sản không thuộc người chết không cần sự chấp thuận của người thừa kế để loại khỏi di sản.'],B:['Ghi vào di sản vì việc giao tiền gắn với tang lễ, dù người được tặng là người vợ.','Mục đích và địa điểm giao tiền không làm thay đổi chủ thể nhận tặng đã được xác định.'],D:['Chia cho các đồng thừa kế, trong đó người vợ hưởng phần của mình theo hàng thừa kế.','Không áp dụng chia thừa kế cho khoản tặng riêng chưa từng thuộc người chết.']}
},
'REFIN26-CC-013':{
 reason:'Bỏ chỉ dẫn phân biệt cấp lại với bổ nhiệm; thay nhiễu sửa tay bằng cách xử lý hồ sơ dễ nhầm.',
 variants:[
  'Tháng 10/2026, văn phòng nơi công chứng viên K hành nghề đã được đổi tên hợp lệ. Thẻ của K vẫn ghi tên cũ, còn quyết định bổ nhiệm không thay đổi. K cần làm gì đối với thẻ?',
  'Tháng 10/2026, sau khi văn phòng đổi tên, bộ phận nhân sự đề nghị K giữ thẻ cũ vì số quyết định bổ nhiệm vẫn đúng. Phương án nào phù hợp để xử lý thông tin trên thẻ?',
  'Tháng 10/2026, K đang hành nghề tại văn phòng vừa hoàn tất thủ tục đổi tên. K muốn cập nhật thẻ ghi tên cũ nhưng chưa rõ phải thực hiện thủ tục nào. K nên chọn phương án nào?'
 ],
 options:{B:['Tiếp tục dùng thẻ cũ, kèm quyết định đổi tên văn phòng khi cần chứng minh nơi hành nghề.','Giấy tờ kèm theo không thay thủ tục xử lý thẻ theo tên tổ chức đã đổi.'],C:['Làm thủ tục bổ nhiệm lại trước, sau đó đề nghị cấp thẻ theo tên mới.','Đổi tên tổ chức không tự làm mất tư cách được bổ nhiệm của công chứng viên.'],D:['Đề nghị đính chính tên trên thẻ đang dùng mà không thực hiện việc thu hồi, cấp lại.','Trường hợp này được xử lý theo cơ chế thu hồi thẻ tên cũ và cấp lại, không chỉ đính chính.']}
},
'AUTH26-016':{
 reason:'Bỏ trích sẵn điều luật; thay nhiễu biến giấy thành di chúc bằng nhầm lẫn thời điểm chấm dứt đại diện.',
 variants:[
  'Tháng 10/2026, A chết khi giấy ủy quyền cho B bán xe mới được sáu tháng trong thời hạn 24 tháng. Xe chưa bán; B chưa có căn cứ đại diện nào khác nhưng muốn tiếp tục ký nhân danh A. B có thể sử dụng giấy ủy quyền này không?',
  'Tháng 10/2026, B xuất trình giấy ủy quyền bán xe còn thời hạn 18 tháng. Người ủy quyền là A đã chết và B chưa được trao quyền đại diện mới. Việc giấy chưa đến ngày hết hạn có cho phép B tiếp tục ký bán xe nhân danh A không?',
  'Tháng 10/2026, một hồ sơ bán xe dùng giấy ủy quyền 24 tháng do A lập sáu tháng trước. A vừa chết, xe chưa được bán và B không có quyền đại diện mới. Hồ sơ này cần được xử lý thế nào về quyền ký của B?'
 ],
 options:{B:['B được tiếp tục bán nếu những người thừa kế chưa gửi thông báo phản đối việc sử dụng giấy ủy quyền.','Quyền đại diện đã chấm dứt khi A chết, không chờ người thừa kế phản đối.'],C:['B được tiếp tục bán trong thời hạn còn lại nếu hợp đồng ủy quyền chưa bị hủy bằng văn bản.','Căn cứ chấm dứt do cá nhân chết độc lập với việc hủy văn bản và thời hạn còn lại.'],D:['B phải xin xác nhận giấy ủy quyền còn thời hạn rồi mới tiếp tục ký nhân danh A.','Xác nhận ngày hết hạn không khôi phục quyền đại diện đã chấm dứt.']}
},
'COMP26-DN-016':{
 reason:'Đổi câu hỏi có/không sang lựa chọn cách xác định trách nhiệm, cân đối bốn phương án.',
 variants:[
  'Tháng 10/2026, hồ sơ chấm dứt hoạt động chi nhánh có thông tin sai sự thật. Trưởng chi nhánh là người chuẩn bị và ký hồ sơ; người đại diện theo pháp luật của doanh nghiệp cho rằng mình không phải chịu trách nhiệm. Trách nhiệm về tính trung thực, chính xác của hồ sơ được xác định thế nào?',
  'Tháng 10/2026, doanh nghiệp phát hiện hồ sơ chấm dứt chi nhánh do Trưởng chi nhánh lập có thông tin không trung thực. Người đại diện theo pháp luật không trực tiếp lập hồ sơ. Ai chịu trách nhiệm về các thông tin này?',
  'Tháng 10/2026, người đại diện doanh nghiệp và Trưởng chi nhánh đề nghị chỉ người trực tiếp soạn hồ sơ chịu trách nhiệm về thông tin sai trong hồ sơ chấm dứt chi nhánh. Cách xác định trách nhiệm nào phù hợp?'
 ],
 options:{A:['Người đứng đầu chi nhánh chịu trách nhiệm, vì đã trực tiếp chuẩn bị và ký hồ sơ.','Không loại trách nhiệm liên đới của người đại diện doanh nghiệp chỉ vì không trực tiếp lập hồ sơ.'],B:['Hai người chịu trách nhiệm riêng theo từng nội dung được phân công khi lập hồ sơ.','Phân công nội bộ không thay trách nhiệm liên đới về tính trung thực, chính xác của hồ sơ.'],C:['Người đại diện doanh nghiệp chịu trách nhiệm khi hồ sơ còn nợ thuế; đã thanh toán thuế thì do Trưởng chi nhánh chịu.','Tình trạng nợ thuế không phải điều kiện phân chia trách nhiệm về thông tin trong hồ sơ.']}
},
'COMP26-DD-010':{
 reason:'Bỏ nhắc tên nhánh luật; dùng nhầm lẫn giữa bồi thường trực tiếp, hoàn trả và việc nghỉ việc.',
 variants:[
  'Tháng 10/2026, một văn phòng công chứng đã chấm dứt hoạt động. Nhân viên trực tiếp có lỗi gây thiệt hại trong công chứng cũng đã nghỉ việc. Khi người bị thiệt hại yêu cầu bồi thường, nhân viên viện việc chấm dứt hợp đồng lao động để từ chối. Yêu cầu này được xem xét thế nào?',
  'Tháng 10/2026, khách hàng yêu cầu bồi thường thiệt hại do lỗi của một nhân viên trong công chứng. Văn phòng đã chấm dứt hoạt động, người gây thiệt hại không còn làm tại đó. Trách nhiệm của người này được xác định thế nào?',
  'Tháng 10/2026, một nhân viên cũ có lỗi trực tiếp gây thiệt hại cho khách trong công chứng. Đến khi khách yêu cầu bồi thường thì cả việc làm của người này và hoạt động văn phòng đều đã chấm dứt. Phương án nào đúng?'
 ],
 options:{A:['Chuyển yêu cầu đến nơi đang lưu hồ sơ; việc nhận lưu hồ sơ kéo theo trách nhiệm bồi thường thay người có lỗi.','Nhận lưu hồ sơ không tự đồng nghĩa nhận trách nhiệm bồi thường do lỗi của người khác.'],C:['Người gây thiệt hại chỉ có nghĩa vụ hoàn trả sau khi văn phòng cũ đã bồi thường cho khách.','Không áp cơ chế hoàn trả sau bồi thường để loại trách nhiệm trực tiếp khi tổ chức đã chấm dứt.'],D:['Chỉ yêu cầu người có lỗi bồi thường nếu đơn đòi bồi thường đã được gửi trước ngày họ nghỉ việc.','Việc nghỉ việc không tạo mốc loại trừ trách nhiệm như phương án nêu.']}
},
'COMP26-QT-001':{
 reason:'Bỏ lời nhắc phân biệt trang và tờ; tạo bốn phương án song song về đánh số và giáp lai.',
 variants:[
  'Tháng 10/2026, dự thảo văn bản công chứng dài hai trang, được in hai mặt trên một tờ giấy. Bộ phận hoàn thiện hồ sơ cần đánh số trang và đóng dấu giáp lai thế nào?',
  'Tháng 10/2026, nhân viên chuẩn bị văn bản công chứng gồm hai mặt của cùng một tờ giấy. Phương án nào đúng về việc đánh số và giáp lai văn bản này?',
  'Tháng 10/2026, văn bản công chứng đã được bố trí thành hai trang trên một tờ in hai mặt. Trước khi hoàn tất văn bản, nhân viên chọn cách đánh số trang và giáp lai nào?'
 ],
 options:{A:['Đánh số cả hai trang; không phát sinh yêu cầu giáp lai giữa các tờ chỉ từ việc in hai mặt.','Hai trang phải được đánh số; một tờ in hai mặt chưa phải văn bản từ hai tờ.'],B:['Đánh số cả hai trang và giáp lai hai mặt như đối với hai tờ giấy.','Phương án coi hai mặt của một tờ thành hai tờ để áp dụng giáp lai.'],C:['Chỉ đánh số trang đầu và giáp lai hai mặt để bảo đảm liên tục nội dung.','Giáp lai không thay việc đánh số từng trang, đồng thời chưa có hai tờ để giáp lai giữa các tờ.'],D:['Không cần đánh số hoặc giáp lai nếu công chứng viên đã ký trên cả hai mặt.','Chữ ký không thay yêu cầu đánh số của văn bản từ hai trang.']}
},
'FAM26-003':{
 reason:'Bỏ gọi sẵn quy tắc nơi thực hiện; nhiễu dựa vào sao lưu hồ sơ, cùng tỉnh và thỏa thuận lựa chọn.',
 variants:[
  'Tháng 10/2026, vợ chồng H muốn công chứng việc chấm dứt thỏa thuận chia tài sản đã được văn phòng A công chứng. A vẫn hoạt động bình thường và lưu hồ sơ. Hai người đề nghị văn phòng B cùng tỉnh thực hiện vì gần nhà hơn. B nên giải quyết thế nào?',
  'Tháng 10/2026, văn phòng B nhận yêu cầu công chứng việc chấm dứt một thỏa thuận tài sản vợ chồng do A công chứng trước đó. A cùng tỉnh với B, vẫn hoạt động và đang lưu hồ sơ. B cần hướng dẫn khách hàng theo phương án nào?',
  'Tháng 10/2026, hai vợ chồng từng công chứng thỏa thuận nhập tài sản riêng vào tài sản chung tại A. Nay họ cùng yêu cầu chấm dứt thỏa thuận và chọn B cùng tỉnh. A vẫn hoạt động bình thường, giữ hồ sơ gốc. Nơi thực hiện được xác định thế nào?'
 ],
 options:{A:['B có thể thực hiện sau khi nhận bản sao hồ sơ công chứng do A cung cấp.','Bản sao hồ sơ không thay quy tắc thực hiện tại tổ chức đã công chứng khi A còn hoạt động.'],C:['B có thể thực hiện vì quy tắc trở lại A chỉ áp dụng khi thay đổi nội dung, không áp dụng khi chấm dứt.','Khoản 2 Điều 53 còn bao gồm việc chấm dứt giao dịch đã công chứng.'],D:['B có thể thực hiện nếu hai vợ chồng cùng lập văn bản lựa chọn B thay cho A.','Sự lựa chọn của các bên không thay điều kiện về nơi thực hiện trong trường hợp này.']}
},
'COMP26-DN-008':{
 reason:'Nêu mốc thời gian trong hồ sơ thay câu nhắc kiểm tra quy tắc; bỏ nhiễu dựa vào chủ nợ biết đăng ký.',
 variants:[
  'Tháng 10/2026, chủ công ty TNHH một thành viên cam kết góp 5 tỷ đồng nhưng chỉ góp 3 tỷ, sau đó đăng ký giảm vốn đúng thủ tục. Một nghĩa vụ tài chính phát sinh trước ngày cuối cùng phải đăng ký thay đổi vốn. Chủ sở hữu đề nghị chỉ tính trách nhiệm theo 3 tỷ đã góp. Đề nghị này có phù hợp không?',
  'Tháng 10/2026, công ty TNHH một thành viên đã điều chỉnh vốn từ 5 tỷ xuống 3 tỷ do chủ sở hữu góp thiếu. Khi giải quyết nghĩa vụ phát sinh trước hạn cuối phải đăng ký thay đổi, chủ sở hữu viện mức vốn mới để giới hạn trách nhiệm. Cách xác định nào đúng?',
  'Tháng 10/2026, giấy đăng ký mới của công ty TNHH một thành viên ghi vốn 3 tỷ đồng thay cho 5 tỷ đã cam kết. Nghĩa vụ đang tranh chấp phát sinh trước ngày cuối cùng phải đăng ký điều chỉnh do góp thiếu. Mức vốn mới có làm thay đổi trách nhiệm đối với nghĩa vụ này không?'
 ],
 options:{A:['Có; mức 3 tỷ trên đăng ký mới được dùng cho nghĩa vụ chưa thanh toán tại thời điểm giảm vốn.','Đăng ký giảm vốn không hồi tố xóa trách nhiệm tương ứng mức vốn đã cam kết trong thời kỳ luật định.'],B:['Có; chủ sở hữu chỉ chịu thêm tối đa 2 tỷ chưa góp, thay cho trách nhiệm tính trên vốn cam kết.','Phần thiếu không phải căn cứ thay thế toàn bộ mức vốn cam kết khi xác định trách nhiệm ở nhánh này.'],C:['Không, nhưng mức vốn cam kết chỉ áp dụng nếu chủ nợ đã yêu cầu thanh toán trước ngày giảm vốn.','Luật gắn mốc với thời điểm phát sinh nghĩa vụ, không phải ngày chủ nợ yêu cầu thanh toán.']}
},
'AUTH26-020':{
 reason:'Giữ tình trạng tay và quyền đại diện; thay nhiễu giả điểm chỉ bằng nhầm lẫn cần người làm chứng hoặc ủy quyền.',
 variants:[
  'Tháng 10/2026, B trực tiếp tham gia giao dịch nhưng gãy tay phải nên không ký được. Ngón trỏ trái vẫn điểm chỉ được; các điều kiện công chứng khác đã đáp ứng. Chồng B, không có quyền đại diện, đề nghị ký tên B thay. Công chứng viên nên xử lý thế nào?',
  'Tháng 10/2026, B không thể ký do gãy tay phải, nhưng có thể dùng ngón trỏ trái để điểm chỉ. Chồng muốn ký thay dù chưa có quyền đại diện; hồ sơ đã đáp ứng các điều kiện khác. Phương án nào phù hợp?',
  'Tháng 10/2026, một hồ sơ đã đủ các điều kiện công chứng khác nhưng người tham gia B không ký được vì gãy tay phải. B còn dùng được ngón trỏ trái, còn chồng B xin ký thay mà không có quyền đại diện. Việc thể hiện ý chí trên văn bản được thực hiện thế nào?'
 ],
 options:{A:['Hẹn B ký sau khi tay hồi phục, vì chỉ ngón trỏ phải mới được dùng để thay chữ ký.','Khi không dùng được ngón trỏ phải, luật cho phép dùng ngón trỏ trái.'],B:['Để chồng ký thay nếu B xác nhận đồng ý ngay trước mặt công chứng viên.','Sự đồng ý tại chỗ không cho phép người không có quyền đại diện ký tên B thay.'],C:['Yêu cầu B lập ủy quyền cho chồng rồi mới tiếp tục, dù B có thể tự điểm chỉ.','Điểm chỉ thay ký là cơ chế có thể áp dụng; không bắt buộc chuyển sang đại diện theo ủy quyền.']}
},
'FAM26-024':{
 reason:'Giữ giới hạn về tặng cho; thay lý do tùy tiện bằng nhầm lẫn về giám sát và mục đích sử dụng tài sản.',
 variants:[
  'Tháng 10/2026, chồng là người giám hộ hợp lệ của vợ đã mất năng lực hành vi dân sự. Ông muốn nhân danh vợ tặng tài sản riêng của bà cho cháu và đã được người giám sát đồng ý. Giao dịch dự kiến được đánh giá thế nào?',
  'Tháng 10/2026, một người chồng đang giám hộ cho vợ mất năng lực đề nghị ký hợp đồng tặng tài sản riêng của vợ cho cháu. Người giám sát việc giám hộ đã chấp thuận. Ông có thể thực hiện giao dịch này không?',
  'Tháng 10/2026, người chồng làm giám hộ cho vợ mất năng lực muốn tặng tài sản riêng của bà cho tổ chức từ thiện. Người giám sát đồng ý và ông cho rằng mục đích tặng là phù hợp. Phương án nào đúng?'
 ],
 options:{A:['Có thể tặng nếu tài sản không cần dùng cho chi phí sinh hoạt và chăm sóc người vợ.','Việc còn tài sản để chăm sóc không tạo ngoại lệ cho lệnh cấm đem tài sản người được giám hộ tặng cho người khác.'],C:['Có thể tặng sau khi có chấp thuận bằng văn bản của người giám sát việc giám hộ.','Sự đồng ý của người giám sát không hợp thức hóa loại giao dịch tặng cho bị cấm này.'],D:['Có thể tặng nếu người nhận cam kết sử dụng tài sản cho mục đích gia đình hoặc xã hội.','Mục đích sử dụng của người nhận không thay giới hạn đối với quyền của người giám hộ.']}
},
'DEP26-016':{
 reason:'Bỏ nêu sẵn trần 5% ở một biến thể; giữ đủ giá và điều kiện kinh doanh để tự chọn quy tắc.',
 variants:[
  'Tháng 10/2026, chủ đầu tư chào bán căn hộ hình thành trong tương lai đã đủ điều kiện đưa vào kinh doanh, giá 4 tỷ đồng. Chủ đầu tư đề nghị khách đặt cọc 300 triệu đồng. Phương án nào đúng về khoản thu này?',
  'Tháng 10/2026, khách hàng đồng ý mua căn hộ hình thành trong tương lai với giá 4 tỷ đồng. Dự án đã đủ điều kiện kinh doanh; chủ đầu tư dự kiến thu 300 triệu đồng khi ký thỏa thuận đặt cọc. Khoản thu cần được xử lý thế nào?',
  'Tháng 10/2026, chủ đầu tư cho rằng có thể nhận 300 triệu đồng cọc cho căn hộ hình thành trong tương lai giá 4 tỷ đồng vì còn thấp hơn giới hạn thanh toán lần đầu. Căn hộ đã đủ điều kiện đưa vào kinh doanh. Nhận định nào phù hợp?'
 ],
 options:{A:['Được thu 300 triệu nếu thỏa thuận đặt cọc ghi rõ đây chưa phải tiền thanh toán lần đầu.','Đổi cách gọi không loại giới hạn riêng đối với tiền cọc của chủ đầu tư.'],B:['Được thu 300 triệu vì khoản này thấp hơn 30% giá bán căn hộ.','Giới hạn thanh toán lần đầu không thay giới hạn riêng của khoản cọc.'],C:['Chỉ được nhận cọc sau khi ký hợp đồng mua bán, dù căn hộ đã đủ điều kiện kinh doanh.','Không phải chờ ký hợp đồng mua bán mới được nhận cọc theo quy tắc được hỏi; mức thu mới là điểm chưa phù hợp.']}
},
'DEP26-006':{
 reason:'Giữ điều khoản số tiền rõ ràng; nhiễu thể hiện nhầm tiền hoàn, tiền trả thêm và quy tắc mặc định.',
 variants:[
  'Tháng 10/2026, hợp đồng đặt cọc dân sự ghi: bên nhận 300 triệu đồng cọc phải hoàn lại số tiền này và trả thêm 900 triệu nếu tự ý từ chối giao kết. Bên nhận cọc đã từ chối, không có căn cứ miễn trách nhiệm. Số tiền phải trả được xác định thế nào?',
  'Tháng 10/2026, bên nhận cọc tự ý từ chối giao kết và đề nghị trả tổng cộng 600 triệu đồng. Thỏa thuận trước đó ghi rõ phải hoàn 300 triệu tiền cọc và trả thêm 900 triệu; không có căn cứ miễn trách nhiệm. Yêu cầu của bên đặt cọc nên được giải quyết thế nào?',
  'Tháng 10/2026, một điều khoản đặt cọc dân sự quy định riêng hai khoản: hoàn lại 300 triệu đồng và trả thêm 900 triệu khi bên nhận tự ý từ chối giao kết. Sự kiện này đã xảy ra và không được miễn trách nhiệm. Phương án nào đúng?'
 ],
 options:{A:['Tổng phải trả là 1,5 tỷ đồng vì cộng tiền hoàn cọc, khoản tương đương cọc theo luật và 900 triệu đã thỏa thuận.','Không cộng quy tắc mặc định thêm một lần vào mức xử lý thay thế đã thỏa thuận.'],C:['Tổng phải trả là 600 triệu đồng theo mức mặc định, còn khoản 900 triệu chỉ được tính khi có thiệt hại tương ứng.','Khoản 2 Điều 328 cho phép thỏa thuận khác; không tự chuyển khoản đã thỏa thuận thành bồi thường phải chứng minh thiệt hại.'],D:['Tổng phải trả là 900 triệu đồng vì hiểu đây là toàn bộ mức xử lý thay cho quy tắc mặc định.','Điều khoản đã tách rõ hoàn 300 triệu và trả thêm 900 triệu, không gộp hai khoản thành 900 triệu.']}
},
'SRC26-002':{
 reason:'Không nêu sẵn hệ số ba lần trong biến thể; nhiễu là các mốc số lượng thay vì lập luận phi lý.',
 variants:[
  'Tháng 10/2026, một đề trắc nghiệm giả định theo khoản 3 Điều 29 Thông tư 06/2025/TT-BTP có 60 câu. Nhóm xây dựng ngân hàng hiện có 150 câu hợp lệ, đáp ứng thiết kế phần mềm. Để đạt yêu cầu tối thiểu về số lượng, cần bổ sung bao nhiêu câu?',
  'Tháng 10/2026, nhóm biên soạn đã hoàn thành 150 câu hợp lệ cho một đề trắc nghiệm giả định gồm 60 câu theo khoản 3 Điều 29 Thông tư 06/2025/TT-BTP. Nhóm còn phải bổ sung tối thiểu bao nhiêu câu để đáp ứng yêu cầu về ngân hàng?',
  'Tháng 10/2026, ngân hàng dùng cho một đề giả định 60 câu có 180 câu, nhưng 30 câu vừa bị loại vì không đạt. Theo yêu cầu số lượng tại khoản 3 Điều 29 Thông tư 06/2025/TT-BTP, cần bổ sung tối thiểu bao nhiêu câu hợp lệ?'
 ],
 options:{A:['Không cần bổ sung.','150 câu mới bằng 2,5 lần đề 60 câu, chưa đạt mức tối thiểu ba lần.'],B:['30 câu.','Cần đạt 180 câu hợp lệ; 180 trừ 150 bằng 30.'],C:['10 câu.','160 câu vẫn chưa đạt mức tối thiểu 180 câu.'],D:['60 câu.','210 câu vượt mức tối thiểu; câu hỏi yêu cầu số cần bổ sung ít nhất.']}
},
'REFIN26-CC-005':{
 reason:'Bỏ yêu cầu phân biệt đã gợi giải; tăng nhiễu về việc thuê hỗ trợ so với thuê điều hành.',
 variants:['Tháng 10/2026, công chứng viên K là Trưởng văn phòng hợp danh P. P ký với M, người không phải công chứng viên, hai hợp đồng: I giao hỗ trợ lưu trữ, hành chính dưới sự điều hành của K; II giao M toàn quyền điều hành, K chỉ ký lời chứng. Theo II, khi K vắng mặt M còn được dùng thẻ của K để ký chứng nhận. Phương án nào đúng về các thỏa thuận này?'],
 options:{B:['I và II có thể thực hiện nếu K giữ quyền kiểm tra hồ sơ và ký xác nhận lại những việc M đã làm.','Kiểm tra hoặc ký lại không hợp thức hóa việc thuê người điều hành và cho dùng thẻ để chứng nhận.'],C:['I không được thực hiện vì lưu trữ là nghiệp vụ công chứng; II được thực hiện nếu M có chuyên môn quản trị.','Hỗ trợ hành chính dưới sự điều hành không đồng nhất với cho thuê người điều hành; chuyên môn quản trị không thay điều kiện luật định.'],D:['I được thực hiện; II cần đổi thành hợp đồng tư vấn và ghi K chịu trách nhiệm về chữ ký của M.','Tên hợp đồng và cam kết chịu trách nhiệm không thay quyền thực giao hoặc tư cách người chứng nhận.']}
},
'REFIN26-DAT-001':{
 reason:'Bỏ gợi ý tách hai đối tượng; các nhiễu đều dựa vào nhầm chế độ thuê đất và sở hữu nhà xưởng.',
 variants:[
  'Tháng 10/2026, cá nhân H thuê đất của Nhà nước trả tiền hằng năm và sở hữu hợp pháp nhà xưởng trên đất. Hồ sơ vay vốn đề nghị thế chấp cả nhà xưởng và quyền sử dụng đất thuê. Đối tượng nào phù hợp với quyền thế chấp của H?',
  'Tháng 10/2026, ngân hàng nhận đề nghị thế chấp nhà xưởng cùng quyền sử dụng đất của H. Nhà xưởng thuộc sở hữu hợp pháp của H; đất do Nhà nước cho thuê trả tiền hằng năm. Phương án nào đúng về đối tượng bảo đảm?',
  'Tháng 10/2026, H muốn vay vốn bằng tài sản tại khu đất thuê Nhà nước trả tiền hằng năm. H sở hữu hợp pháp nhà xưởng trên đất và muốn đưa cả đất, nhà xưởng vào hợp đồng thế chấp. Hồ sơ nên xác định đối tượng thế chấp thế nào?'
 ],
 options:{A:['Cả nhà xưởng và quyền sử dụng đất thuê vì công trình gắn liền với đất trong suốt thời hạn thuê.','Sở hữu công trình không làm quyền sử dụng đất thuê trả hằng năm được thế chấp theo cùng cơ chế.'],C:['Chỉ quyền sử dụng đất trong thời hạn thuê còn lại, còn nhà xưởng phải đưa vào hợp đồng cầm cố riêng.','Nhánh luật cho thế chấp tài sản thuộc sở hữu gắn liền đất, không phải quyền sử dụng đất thuê hằng năm như phương án nêu.'],D:['Nhà xưởng, nhưng chỉ sau khi chuyển hình thức thuê sang trả tiền một lần cho thời gian còn lại.','Không có yêu cầu phải đổi hình thức trả tiền thuê mới được thế chấp tài sản hợp pháp gắn liền đất theo nhánh này.']}
},
'IMP-T60-095':{
 reason:'Giới thiệu tên M nhất quán, bỏ trích khoản và lời nhắc giới hạn sẵn; giữ câu hỏi về sự đồng ý của đại diện.',
 variants:[
  'Tháng 10/2026, M 16 tuổi muốn tự ký hợp đồng lao động. Về sự đồng ý của người đại diện, M cần đáp ứng yêu cầu nào?',
  'Tháng 10/2026, M 16 tuổi đến ký hợp đồng lao động và nói anh chị đã đồng ý miệng. Để M tự giao kết, người sử dụng lao động cần yêu cầu gì về sự đồng ý của người đại diện?',
  'Tháng 10/2026, doanh nghiệp chuẩn bị hợp đồng để M 16 tuổi tự ký. Bộ phận nhân sự cho rằng M đã trên 15 tuổi nên không cần giấy đồng ý. Phương án nào đúng về yêu cầu đối với người đại diện?'
 ],
 options:{A:['Có sự đồng ý của người đại diện theo pháp luật, được ghi nhận bằng lời nói khi giao kết.','Nhóm tuổi này cần sự đồng ý bằng văn bản, không chỉ bằng lời nói.'],C:['Người đại diện theo pháp luật phải ký hợp đồng thay M, còn M chỉ xác nhận đã đọc.','Không đồng nhất cơ chế đồng ý cho người từ đủ 15 đến dưới 18 tự giao kết với ký thay.'],D:['Có văn bản của người thân đã thành niên xác nhận M đủ khả năng tự làm việc.','Không thay người đại diện theo pháp luật bằng bất kỳ người thân đã thành niên nào.']}
},
'VER26-099':{
 reason:'Rút gọn câu dẫn, thay nhiễu cấm mọi ủy quyền bằng nhầm lẫn giữa nghị quyết, nộp hồ sơ và ký.',
 variants:['Tháng 10/2026, công ty có hai người đại diện theo pháp luật: P được ký hợp đồng đến 1 tỷ đồng, Q được ký trên 1 tỷ theo điều lệ. Cấp có thẩm quyền đã chấp thuận bán tài sản giá 2 tỷ. K chỉ được P giao nộp hồ sơ nhưng muốn ký hợp đồng tại tổ chức công chứng. Hồ sơ cần được xử lý thế nào về người ký?'],
 options:{A:['K được ký nếu P xác nhận việc giao nộp hồ sơ bao gồm hoàn tất giao dịch đã được công ty chấp thuận.','P không thể dùng xác nhận này vượt phạm vi được điều lệ phân định; giao nộp hồ sơ chưa phải quyền ký.'],B:['K được ký vì nghị quyết duyệt bán 2 tỷ đã giải quyết việc phân quyền giữa P và Q.','Quyết định phê duyệt nội bộ không tự trao quyền đại diện ký hợp đồng cho K.'],D:['P phải cùng K ký để bổ sung quyền còn thiếu; không cần xem xét vai trò của Q trong điều lệ.','Chữ ký của P không tự khắc phục giới hạn trên 1 tỷ đã phân cho Q.']}
},
'CC-035':{
 reason:'Bỏ câu hỏi yêu cầu tự phân biệt chủ thể; nhiễu tập trung vào tư cách luật sư và công chứng viên.',
 variants:['Tháng 10/2026, khách hàng nhờ công ty luật L soạn hợp đồng rồi đề nghị luật sư của L ký lời chứng, đóng dấu công ty để dùng như văn bản công chứng. Không có công chứng viên của tổ chức hành nghề công chứng tham gia. L nên giải quyết yêu cầu này thế nào?'],
 options:{B:['Có thể ký lời chứng nếu luật sư được khách hàng ủy quyền thực hiện toàn bộ thủ tục và chịu trách nhiệm nội dung.','Ủy quyền của khách hàng không trao tư cách công chứng viên hoặc tổ chức hành nghề công chứng.'],C:['Có thể ký nếu đây là yêu cầu công chứng tự nguyện; giao dịch bắt buộc công chứng mới phải chuyển đến tổ chức công chứng.','Yêu cầu tự nguyện vẫn phải do đúng chủ thể thực hiện theo luật công chứng.'],D:['Có thể dùng lời chứng của L nếu sau đó một văn phòng công chứng xác nhận con dấu công ty luật.','Xác nhận con dấu không biến lời chứng do chủ thể không có thẩm quyền lập thành văn bản công chứng.']}
},
'IMP-T60-069':{
 reason:'Giảm câu dẫn 571 ký tự, bỏ câu nhắc phân biệt quyền đại diện và phê duyệt; giữ đủ hai tỷ lệ và ngưỡng điều lệ.',
 variants:['Tháng 10/2026, giám đốc có quyền đại diện của công ty TNHH hai thành viên dự định ký hai hợp đồng bán tài sản: I bằng 45%, II bằng 35% tổng tài sản theo báo cáo tài chính gần nhất. Điều lệ hợp lệ yêu cầu Hội đồng thành viên thông qua giao dịch từ 40%; không có căn cứ phê duyệt khác đối với II. I chưa được thông qua. Giám đốc có thể ký hai hợp đồng thế nào?'],
 options:{A:['Được ký cả I và II vì tư cách đại diện cho phép giám đốc quyết định trong phạm vi dưới 50%.','Quyền đại diện không thay việc đáp ứng ngưỡng phê duyệt hợp lệ của điều lệ.'],B:['Được ký cả I và II vì ngưỡng 50% của luật được ưu tiên so với ngưỡng 40% trong điều lệ.','Luật cho phép điều lệ đặt tỷ lệ thấp hơn; không bỏ ngưỡng 40% hợp lệ.'],C:['Phải xin thông qua cả I và II vì tổng giá trị hai giao dịch vượt ngưỡng 40%.','Dữ kiện xác định hai giao dịch riêng và không có căn cứ phê duyệt khác cho II; không tự gộp giá trị để đổi kết quả.']}
},
'INH26-003':{
 reason:'Bỏ câu hỏi tự gọi tên quan hệ cha con; giữ phạm vi ba người để tránh suy diễn tỷ lệ chia.',
 variants:[
  'Tháng 10/2026, ông Hòa chết không có di chúc và không có vợ mới. Hòa và Liên đã ly hôn có hiệu lực; con Hảo được giao Liên nuôi, con Hóa sống với Hòa. Cả hai là con đẻ, còn sống và không có căn cứ loại trừ quyền hưởng. Trong ba người Liên, Hảo, Hóa, ai có tư cách thừa kế theo pháp luật?',
  'Tháng 10/2026, khi lập hồ sơ thừa kế của Hòa, gia đình đề nghị bỏ Hảo vì sau ly hôn Hảo ở với mẹ là Liên. Hóa là con đẻ sống với Hòa. Quyết định ly hôn đã có hiệu lực; Hòa không có vợ mới, không để di chúc, hai con đều còn sống và không mất quyền hưởng. Nhận định nào đúng về ba người này?',
  'Tháng 10/2026, Hảo và Hóa làm thủ tục thừa kế của cha là Hòa. Sau ly hôn có hiệu lực, Liên nuôi Hảo, Hòa nuôi Hóa. Hòa chết không di chúc, không có vợ mới; cả hai con đẻ còn sống, không bị loại quyền hưởng. Danh sách gồm Liên, Hảo, Hóa cần được xác định thế nào?'
 ],
 options:{B:['Liên và Hóa có tư cách hưởng; Liên nhận thay vị trí của Hảo vì được giao trực tiếp nuôi con.','Việc trực tiếp nuôi con không chuyển quyền hưởng của con sang người mẹ.'],C:['Chỉ Hóa có tư cách hưởng vì Hảo đã được xác định thuộc hộ của Liên sau ly hôn.','Việc ở khác hộ hoặc giao nuôi không chấm dứt quan hệ cha con để thừa kế.'],D:['Hóa hưởng trực tiếp; phần của Hảo thuộc Liên vì Liên là người trực tiếp chăm sóc Hảo.','Đại diện hoặc chăm sóc con không đồng nghĩa sở hữu phần di sản của con.']}
},
'SRC26-007':{
 reason:'Bỏ câu hỏi nhắc trước giới hạn địa bàn; phương án sai dùng các thủ tục người làm hồ sơ có thể nhầm.',
 variants:[
  'Tháng 10/2026, hai chủ đất muốn lập một hợp đồng chuyển nhượng duy nhất cho hai thửa ở tỉnh X và tỉnh Y. Cả hai thửa đều đủ điều kiện chuyển nhượng. Họ chọn văn phòng công chứng tại X và đề nghị chứng nhận toàn bộ hợp đồng. Văn phòng nên xử lý thế nào?',
  'Tháng 10/2026, văn phòng công chứng tại X nhận dự thảo một hợp đồng chuyển nhượng gồm đất tại X và Y. Các chủ sở hữu đều có mặt, các thửa đủ điều kiện bán và giao dịch không thuộc ngoại lệ Điều 44. Phương án nào đúng?',
  'Tháng 10/2026, hai bên gộp chuyển nhượng hai thửa đất ở hai tỉnh vào một hợp đồng tại văn phòng nơi có một thửa. Họ dự kiến đăng ký từng thửa tại cơ quan của tỉnh tương ứng. Văn phòng có thể giải quyết đề nghị công chứng toàn bộ thế nào?'
 ],
 options:{A:['Có thể thực hiện toàn bộ nếu văn phòng tại Y đã xác minh và gửi đủ thông tin thửa đất ở Y.','Xác minh thông tin không mở rộng địa hạt công chứng hợp đồng chuyển nhượng.'],B:['Có thể thực hiện toàn bộ nếu các bên chọn X làm nơi giao kết và nhận tiền theo hợp đồng.','Thỏa thuận nơi giao kết, thanh toán không thay giới hạn địa bàn đối với bất động sản.'],D:['Có thể thực hiện toàn bộ vì thủ tục đăng ký biến động vẫn được tách theo từng tỉnh.','Phân chia nơi đăng ký không tạo ngoại lệ cho thẩm quyền công chứng toàn bộ hợp đồng.']}
},
'REFIN26-CC-030':{
 reason:'Rút diễn giải, bỏ nhận định sai lộ liễu ở câu dẫn; giữ đủ hai điều kiện còn thiếu.',
 variants:['Tháng 10/2026, K muốn mua văn phòng công chứng P theo mô hình doanh nghiệp tư nhân, đã hoạt động hợp pháp ba năm. K đã hành nghề ba năm, mới chấm dứt tư cách thành viên hợp danh tại Q một năm và dự định thuê người khác làm Trưởng P. Không có ngoại lệ luật định khác. Phương án nào đúng về điều kiện của K?'],
 options:{A:['K đã đủ điều kiện về thời gian và có thể thuê công chứng viên khác làm Trưởng P.','K còn thiếu thời gian sau chấm dứt hợp danh và cam kết cá nhân hành nghề làm Trưởng nơi mua.'],C:['K cần cam kết tự làm Trưởng P; ba năm hành nghề đã đủ để không phải chờ thêm.','Không dùng kinh nghiệm hành nghề thay mốc thời gian tính từ chấm dứt tư cách hợp danh.'],D:['K cần chờ thêm một năm; việc bố trí người khác làm Trưởng P có thể thỏa thuận sau.','Đủ thời gian không thay yêu cầu người mua cam kết hành nghề làm Trưởng.']}
},
'VER26-034':{
 reason:'Giảm mệnh đề và lời nhân vật chỉ ra đáp án; nhiễu là ba tổ hợp tài sản riêng/chung có thể nhầm.',
 variants:['Tháng 10/2026, A và W chấm dứt hiệu lực việc chia tài sản chung trong thời kỳ hôn nhân theo đúng hình thức. Chiếc xe đã được chia hợp lệ thành tài sản riêng của A trước đó, nay hai người không thỏa thuận nhập lại. Sau khi chấm dứt việc chia, W có tiền lương mới; không có căn cứ xác định khoản lương là tài sản riêng. Xe và tiền lương được xác định thế nào?'],
 options:{A:['Xe trở lại tài sản chung; tiền lương mới của W là tài sản riêng theo việc chia trước đó.','Chấm dứt việc chia không tự nhập lại xe và không duy trì chế độ riêng cho tiền lương mới theo cách này.'],C:['Xe vẫn là tài sản riêng của A; tiền lương mới vẫn riêng của W cho đến khi có thỏa thuận nhập chung.','Phương án kéo dài hệ quả của việc chia trước sang khoản lương sau khi đã chấm dứt.'],D:['Cả xe và tiền lương mới đều là tài sản chung kể từ ngày chấm dứt hiệu lực việc chia.','Tài sản đã chia vẫn riêng nếu không có thỏa thuận khác; không đồng nhất với tài sản phát sinh sau mốc chấm dứt.']}
},
'VER26-084':{
 reason:'Rút câu dẫn; nhiễu dựa vào nhầm giữa năng lực, sự đồng ý và hình thức công chứng.',
 variants:['Tháng 10/2026, K đang bị Tòa án hạn chế năng lực hành vi dân sự; P là người đại diện. K mua thực phẩm cho sinh hoạt hằng ngày và bán chiếc máy giá trị lớn của mình. P đồng ý miệng việc mua thực phẩm nhưng không đồng ý bán máy; việc bán không thuộc nhu cầu sinh hoạt hoặc ngoại lệ khác. Người mua máy cam kết tự chịu trách nhiệm. Phương án nào đúng?'],
 options:{A:['K tự thực hiện cả hai việc vì còn quyền sở hữu, còn cam kết của người mua đủ giải quyết việc bán máy.','Quyền sở hữu không loại yêu cầu có sự đồng ý của đại diện ở giao dịch bán máy trong đề.'],B:['P phải trực tiếp ký cả hai giao dịch; K chỉ được thực hiện sau khi Tòa án hủy quyết định hạn chế.','Phương án bỏ ngoại lệ nhu cầu sinh hoạt hằng ngày và đồng nhất hạn chế với không được tham gia giao dịch.'],C:['Việc mua thực phẩm cần P đồng ý; việc bán máy có thể tiến hành nếu được công chứng.','Ngoại lệ sinh hoạt bị đảo ngược; công chứng không thay sự đồng ý của người đại diện ở giao dịch còn lại.']}
},
'CAL26-057':{
 reason:'Giữ giới hạn kết luận để tránh biến ngoại lệ thành miễn mọi trách nhiệm; viết lại các dữ kiện phủ định cho dễ đọc.',
 variants:['N được ủy quyền mua hàng tối đa 500 triệu đồng nhưng ký mua 650 triệu. Bên bán biết rõ giới hạn này khi ký. Người ủy quyền phản đối ngay khi biết việc và không gây lỗi khiến bên bán hiểu nhầm. Bên bán yêu cầu N tự thực hiện phần 150 triệu theo trách nhiệm của người đại diện vượt phạm vi. Yêu cầu đối với N được giải quyết thế nào?'],
 options:{A:['Có, nhưng người ủy quyền phải trả trước đủ 650 triệu rồi yêu cầu N hoàn lại 150 triệu.','Không có dữ kiện làm phát sinh trách nhiệm của người ủy quyền đối với phần vượt theo nhánh được hỏi.'],C:['Có, vì việc bên bán biết giới hạn chỉ ảnh hưởng quyền đòi người ủy quyền, không ảnh hưởng quyền đòi N.','Ngoại lệ biết hoặc phải biết còn liên quan chính trách nhiệm thực hiện phần vượt của người đại diện.'],D:['Không; việc biết giới hạn cũng loại mọi yêu cầu khác đối với N phát sinh từ hợp đồng này.','Không được mở rộng kết luận của khoản 2 thành miễn trách nhiệm theo tất cả căn cứ khác.']}
},
'CAL26-062':{
 reason:'Tách rõ hai hồ sơ, giữ giới hạn cơ chế lựa chọn trước nhưng không nhắc sẵn hai điều kiện cần kiểm tra.',
 variants:['A khi còn đủ năng lực đã công chứng văn bản chọn B làm người giám hộ. Đến khi A cần giám hộ, B từ chối nhận. Một hồ sơ khác chỉ có giấy viết tay chọn C, không được công chứng hoặc chứng thực. Với hai hồ sơ lựa chọn trước này, chưa xem xét việc cử hoặc chỉ định theo căn cứ khác, kết luận nào đúng?'],
 options:{A:['B phải nhận theo văn bản đã công chứng; giấy chọn C chỉ cần C xác nhận đồng ý là có hiệu lực lựa chọn trước.','Văn bản công chứng không thay sự đồng ý của B; sự đồng ý của C không tự khắc phục hình thức còn thiếu.'],B:['B được từ chối; C được công nhận theo giấy viết tay nếu có đủ điều kiện làm giám hộ.','Đủ điều kiện cá nhân chưa thay hình thức của văn bản lựa chọn trước.'],D:['B phải thực hiện cho đến khi văn bản chọn B bị hủy; C phải chờ đăng ký giấy viết tay để được xem xét theo cơ chế này.','Không bắt B nhận khi chưa đồng ý; đăng ký không thay yêu cầu công chứng hoặc chứng thực văn bản lựa chọn trước.']}
},
'CAL26-065':{
 reason:'Diễn đạt cụ thể giấy tờ, bỏ câu nhắc ngoại lệ; giữ hai trạng thái đã khai thác và mới có khả năng truy cập.',
 variants:['Một tổ chức công chứng có tài khoản truy cập cơ sở dữ liệu. Ở hồ sơ A, tổ chức đã khai thác hợp pháp đủ thông tin tương ứng giấy tờ tại điểm b, c, d khoản 1 Điều 42. Ở hồ sơ B, tổ chức chưa khai thác được, khách chỉ xác nhận dữ liệu có sẵn. Cả hai hồ sơ có dự thảo giao dịch. Việc nộp các giấy tờ và phí khai thác được xử lý thế nào?'],
 options:{B:['A và B đều không phải nộp giấy tờ b, c, d vì tổ chức đã được cấp tài khoản truy cập.','Khả năng truy cập không đồng nghĩa đã khai thác được thông tin của từng hồ sơ.'],C:['A không phải nộp lại giấy tờ đã khai thác và không chịu phí; B chỉ cần cam đoan dữ liệu có sẵn.','Ngoại lệ không tự miễn phí; cam đoan không thay kết quả khai thác ở B.'],D:['A vẫn phải nộp bản sao để đối chiếu dữ liệu; B được thay giấy tờ bằng bản chụp màn hình do khách cung cấp.','Phương án vừa bỏ ngoại lệ đã đủ điều kiện ở A vừa tạo cách thay thế chưa có căn cứ ở B.']}
},
'CAL26-081':{
 reason:'Bỏ lời nhắc đồng thời các bước; để lựa chọn thể hiện ba nhầm lẫn về lợi ích, quyền quyết định và độ tuổi.',
 variants:['C 13 tuổi có một căn nhà riêng do cha mẹ quản lý, không có người giám hộ khác. Cha muốn bán nhà để chi việc học của C; mẹ chưa đồng ý, còn C muốn giữ nhà. Cha cho rằng mục đích học tập đã đủ và chỉ cần hỏi ý kiến con khi con đủ 15 tuổi. Phương án nào phù hợp khi giải quyết đề nghị bán nhà?'],
 options:{A:['Cha được quyết định nếu chứng minh toàn bộ tiền bán sẽ dùng cho việc học, mẹ được thông báo khi ký.','Mục đích vì lợi ích của con không thay sự thỏa thuận của cha mẹ và việc xem xét nguyện vọng con.'],B:['Ý kiến giữ nhà của C quyết định việc bán vì C đã trên 9 tuổi; cha mẹ phải làm theo ý kiến đó.','Xem xét nguyện vọng không đồng nghĩa chuyển toàn bộ quyền quyết định cho con.'],C:['Cha mẹ cần thống nhất việc bán; nguyện vọng C chỉ phải xem xét khi con đủ 15 tuổi.','Mốc xem xét nguyện vọng trong trường hợp này không phải đợi đến đủ 15 tuổi.']}
},
'CAL26-084':{
 reason:'Bỏ lời nhắc giới hạn đã miễn có hiệu lực khỏi câu hỏi nhưng giữ làm dữ kiện; nhiễu không còn vô hiệu toàn giao dịch.',
 variants:['A nợ B 100 triệu đồng và đã trả 70 triệu. B đã miễn hợp pháp 30 triệu còn lại, không kèm điều kiện hoặc giữ nghĩa vụ phụ. Biên nhận chỉ ghi số thực trả 70 triệu. Sau đó B đổi ý, yêu cầu trả thêm vì biên nhận chưa ghi đủ 100 triệu. Nghĩa vụ của A được xác định thế nào?'],
 options:{A:['Còn 30 triệu cho đến khi B cấp biên nhận ghi đủ 100 triệu hoặc xác nhận đã thanh toán toàn bộ.','Biên nhận số tiền thực trả không làm mất hiệu lực việc miễn phần nghĩa vụ còn lại.'],C:['Tạm dừng 30 triệu trong thời gian B chưa yêu cầu lại; yêu cầu mới làm khoản này tiếp tục phải trả.','Miễn nghĩa vụ hợp pháp không phải thỏa thuận tạm hoãn có thể đòi lại theo cách này.'],D:['Đã chấm dứt nhưng chỉ vào ngày B cấp giấy xác nhận hoàn thành, không phải khi việc miễn có hiệu lực.','Không tạo thêm điều kiện phải cấp giấy xác nhận để áp dụng hệ quả đã hoàn thành theo dữ kiện.']}
}
};

// These explanations replace abbreviated review notes with reader-facing prose.
const explanations={
 'REFIN26-CC-013':'Việc đổi tên tổ chức làm thông tin trên thẻ không còn phù hợp và phải được xử lý theo Điều 18. Công chứng viên thực hiện thủ tục thu hồi thẻ tên cũ, cấp lại theo tên mới; quyết định bổ nhiệm không vì thế mà phải làm lại. Không dùng giấy đổi tên kèm theo hoặc tự sửa thẻ để thay thủ tục này.',
 'COMP26-DD-010':'Điều 40 quy định trường hợp tổ chức hành nghề đã chấm dứt hoạt động thì người trực tiếp có lỗi gây thiệt hại phải tự bồi thường, kể cả khi không còn là nhân viên của tổ chức. Cần phân biệt nghĩa vụ này với việc hoàn trả cho tổ chức sau khi tổ chức bồi thường. Việc nghỉ việc hoặc chuyển nơi lưu hồ sơ không tự xóa trách nhiệm của người có lỗi.',
 'COMP26-QT-001':'Điều 51 dùng hai tiêu chí khác nhau: văn bản có từ hai trang phải đánh số thứ tự từng trang; văn bản có từ hai tờ phải đóng dấu giáp lai giữa các tờ. Hai mặt của một tờ là hai trang, chưa phải hai tờ. Vì vậy phải đánh số cả hai trang nhưng không đặt yêu cầu giáp lai giữa các tờ chỉ từ dữ kiện này.',
 'COMP26-DN-008':'Điều 75 Luật Doanh nghiệp giữ trách nhiệm tương ứng số vốn đã cam kết đối với nghĩa vụ tài chính phát sinh trước ngày cuối cùng phải đăng ký thay đổi vốn do góp thiếu. Việc giảm vốn từ 5 xuống 3 tỷ không làm mất trách nhiệm này. Mốc cần xét là lúc nghĩa vụ phát sinh, không phải lúc chủ nợ đòi thanh toán hoặc biết việc giảm vốn.',
 'REFIN26-DAT-001':'Khoản 2 Điều 37 Luật Đất đai cho phép cá nhân thuộc trường hợp thuê đất trả tiền hằng năm thế chấp tài sản thuộc sở hữu của mình gắn liền với đất. Nhà xưởng hợp pháp là đối tượng cần xem xét; không suy từ quyền sở hữu nhà xưởng thành quyền thế chấp chính quyền sử dụng đất thuê theo cơ chế trả tiền một lần. Các điều kiện khác của tài sản bảo đảm vẫn phải được kiểm tra.',
 'VER26-099':'Điều lệ đã phân quyền ký hợp đồng trên 1 tỷ cho Q, trong khi K mới được P giao nộp hồ sơ. Nghị quyết chấp thuận việc bán tài sản giải quyết một yêu cầu nội bộ, không tự trao quyền ký cho K. Khi đối chiếu Điều 137, Điều 141 BLDS và yêu cầu kiểm tra hồ sơ công chứng, phải xác định đúng người có quyền đại diện và phạm vi quyền được giao.',
 'CC-035':'Theo Điều 19, tổ chức hành nghề công chứng gồm Phòng công chứng và Văn phòng công chứng. Việc soạn hợp đồng, có con dấu và thu phí dịch vụ pháp lý không biến công ty luật thành một trong các tổ chức đó. Yêu cầu công chứng tự nguyện cũng phải được thực hiện bởi đúng công chứng viên, tổ chức có thẩm quyền; sự ủy quyền hoặc đồng ý của khách hàng không thay điều kiện này.',
 'CAL26-057':'Khoản 2 Điều 143 BLDS có ngoại lệ khi bên giao dịch biết hoặc phải biết việc vượt phạm vi đại diện mà vẫn giao dịch. Vì bên bán đã biết giới hạn 500 triệu, không thể mặc nhiên dùng cơ chế này buộc N thực hiện phần vượt 150 triệu. Kết luận chỉ nằm trong căn cứ được hỏi; không suy ra người ủy quyền bị ràng buộc hoặc N được miễn mọi trách nhiệm theo căn cứ khác.',
 'CAL26-081':'Việc định đoạt tài sản riêng của C dưới 15 tuổi phải đáp ứng yêu cầu về sự thỏa thuận của cha mẹ và lợi ích của con. C đã trên 9 tuổi nên nguyện vọng giữ nhà cũng phải được xem xét. Mục đích chi cho học tập không thay sự thỏa thuận còn thiếu của mẹ; ngược lại, việc xem xét nguyện vọng không chuyển toàn bộ quyền quyết định sang C.'
};
